-- Documents V1 D4.7 — QA Shared household-fixture RESIDUE census (read-only).
-- After the D4.7 household fixtures (WU1 household and the Human-QA household) were reset through the audited product
-- routes (POS document deletes + POST /api/admin/opportunities/[id]/delete) under authz_q1 run qar_da541c487abf.
-- CHECK: every CRM household table in QA Shared (4acc9386-…) is back to its baseline count from
--   d47-household-baseline-census.sql (taken 2026-10-25T22:05:12Z, before any D4.7 write), and no run-tagged person,
--   household or member remains. documents / document_subject_links / opportunities are reported as DATA only: the
--   Q1-D3 regression fixtures are removed by their own teardowns and measured by the registered ZERO_RESIDUE census.
select question_id, kind, payload
from (
    select 'd47_hh_customers'::text as question_id, 'check'::text as kind,
           'customers ~ qa_shared ~ equals_baseline_3 ~ ' || (coalesce((select case when exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = 'customers' and c.column_name = 'org_id') then (xpath('/row/n/text()', query_to_xml('select count(*) as n from public.customers where org_id = ''4acc9386-c485-486f-aa1f-05d83499d142''::uuid', false, true, '')))[1]::text::int end), -1) = 3)::text as payload,
           '01'::text as sort_key
    union all
    select 'd47_hh_persons'::text as question_id, 'check'::text as kind,
           'persons ~ qa_shared ~ equals_baseline_4 ~ ' || (coalesce((select case when exists (select 1 from information_schema.columns c where c.table_schema = 'public' and c.table_name = 'persons' and c.column_name = 'org_id') then (xpath('/row/n/text()', query_to_xml('select count(*) as n from public.persons where org_id = ''4acc9386-c485-486f-aa1f-05d83499d142''::uuid', false, true, '')))[1]::text::int end), -1) = 4)::text as payload,
